// Node: "Split & Sample Transcripts"   (Code · Run Once for All Items)
// -----------------------------------------------------------------------------
// Input : the parsed mock_transcripts.json from "Extract JSON".
// Output: one item per session, plus a BOUNDED sample (first 40 + last 20 turns)
//         that is the only thing the classifier ever sees.
// -----------------------------------------------------------------------------
const HEAD_TURNS = 40;
const TAIL_TURNS = 20;

// "Extract From File" may hand us { data: [...] }, a single session, or one item
// per session depending on version/settings. Accept all shapes.
function extractSessions(items) {
  const sessions = [];
  for (const { json } of items) {
    if (Array.isArray(json)) sessions.push(...json);
    else if (Array.isArray(json?.data)) sessions.push(...json.data);
    else if (json?.data?.transcript) sessions.push(json.data);
    else if (json?.transcript) sessions.push(json);
  }
  return sessions;
}

// First 40 + last 20 turns. Short transcripts (<= 60 turns) are sent whole,
// so no turn is ever duplicated or dropped from the middle unnecessarily.
function boundedSample(turns) {
  if (turns.length <= HEAD_TURNS + TAIL_TURNS) return turns;
  return [...turns.slice(0, HEAD_TURNS), ...turns.slice(-TAIL_TURNS)];
}

const formatTurn = (t) => `[${t.timestamp ?? '--:--:--'}] ${t.speaker ?? 'Unknown'}: ${t.text.trim()}`;

const sessions = extractSessions($input.all());
if (sessions.length === 0) {
  throw new Error('No sessions found. Expected an array of sessions in /data/mock_transcripts.json');
}

return sessions.map((session) => {
  const turns = (Array.isArray(session.transcript) ? session.transcript : [])
    .filter((t) => t && typeof t.text === 'string' && t.text.trim() !== '');
  const sample = boundedSample(turns);

  return {
    json: {
      session_id: String(session.id ?? '').trim() || 'UNKNOWN',
      title: session.title ?? '',
      session_created_at: session.created_at ?? null,
      participants: Array.isArray(session.participants) ? session.participants : [],
      transcript: turns,
      total_turn_count: turns.length,
      sample_turn_count: sample.length,
      sample_text: sample.map(formatTurn).join('\n'),
    },
    pairedItem: { item: 0 },
  };
});

// Node: "Build Classifier Request"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Builds the Groq chat-completions body for the classification agent.
// temperature 0 + fixed seed + JSON mode => repeatable verdicts.
// -----------------------------------------------------------------------------
const apiKey = String($env.GROQ_API_KEY ?? '').trim();
if (!apiKey) {
  throw new Error('GROQ_API_KEY is empty. Put it in .env, then run: docker compose up -d --force-recreate n8n');
}

const s = $json;
const roster = s.participants
  .map((p) => `- ${p.name} (${p.is_team_member ? 'GenX team member' : 'external guest'})`)
  .join('\n');

const system = [
  'You classify recorded meetings for the GenX Leadership Academy knowledge base.',
  'Pick exactly one meeting_type:',
  '- "Client Coaching": a GenX coach works with an external client leader on their leadership, mindset, team, delegation, feedback or personal effectiveness.',
  '- "Internal Operations": GenX team members talking among themselves about the company\'s own engineering, tooling, bugs, sprints, releases or admin.',
  '- "Sales Discovery": a conversation about buying GenX services: pricing, budgets, retainers, contracts, pilots or scope of work.',
  '- "Other": anything that fits none of the above.',
  'confidence_score is your probability (0.0 to 1.0) that the chosen meeting_type is correct.',
  'summary is one or two plain sentences describing what the meeting was about.',
  'Respond with a single JSON object with exactly these keys:',
  '{"meeting_type": "Client Coaching | Internal Operations | Sales Discovery | Other", "confidence_score": 0.0, "summary": "..."}',
].join('\n');

const user = [
  `Meeting title: ${s.title}`,
  'Participants:',
  roster || '- (none listed)',
  `Transcript sample (${s.sample_turn_count} of ${s.total_turn_count} turns):`,
  s.sample_text,
].join('\n');

return {
  json: {
    ...s,
    classifier_request: {
      model: $env.GROQ_MODEL || 'openai/gpt-oss-120b',
      temperature: 0,
      seed: 42,
      // gpt-oss is a reasoning model: keep reasoning short and out of the reply,
      // and leave enough budget so reasoning can never starve the JSON answer.
      reasoning_effort: 'low',
      include_reasoning: false,
      max_tokens: 1200,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
};

// Node: "Parse Classification"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Turns the raw LLM reply into a validated verdict. Never throws:
// HTTP errors, empty replies, markdown fences, prose around the JSON, unknown
// labels and out-of-range scores all degrade to a safe "Other / 0.0" verdict,
// which the gate then archives instead of ingesting.
// -----------------------------------------------------------------------------
const ALLOWED_TYPES = ['Client Coaching', 'Internal Operations', 'Sales Discovery', 'Other'];
const PASS_TYPE = 'Client Coaching';
const PASS_CONFIDENCE = 0.8;

// Pair this reply with the session it belongs to (n8n paired-item linking).
const { classifier_request, ...session } = $('Build Classifier Request').item.json;
const reply = $json;

function extractJsonObject(text) {
  const cleaned = text.replace(/```(?:json)?/gi, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('No JSON object found in LLM reply');
  return JSON.parse(cleaned.slice(start, end + 1));
}

const normaliseType = (value) => {
  const key = String(value ?? '').trim().toLowerCase();
  return ALLOWED_TYPES.find((t) => t.toLowerCase() === key) ?? 'Other';
};

const normaliseScore = (value) => {
  const n = typeof value === 'string' ? parseFloat(value) : Number(value);
  return Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0;
};

let verdict;
let parseError = null;
try {
  if (reply.error) {
    const msg = typeof reply.error === 'string' ? reply.error : reply.error.message ?? JSON.stringify(reply.error);
    throw new Error(`Classifier request failed: ${msg}`);
  }
  const content = reply?.choices?.[0]?.message?.content;
  if (typeof content !== 'string' || content.trim() === '') throw new Error('Empty classifier reply');
  verdict = extractJsonObject(content);
} catch (err) {
  parseError = err.message;
  verdict = {};
}

const meeting_type = parseError ? 'Other' : normaliseType(verdict.meeting_type);
const confidence_score = parseError ? 0 : Math.round(normaliseScore(verdict.confidence_score) * 1000) / 1000;
const summary = typeof verdict.summary === 'string' && verdict.summary.trim()
  ? verdict.summary.trim()
  : (parseError ? `Classification unavailable: ${parseError}` : '');

const passes = meeting_type === PASS_TYPE && confidence_score >= PASS_CONFIDENCE;
let reject_reason = null;
if (!passes) {
  if (parseError) reject_reason = `classifier_error: ${parseError}`;
  else if (meeting_type !== PASS_TYPE) reject_reason = `meeting_type=${meeting_type}`;
  else reject_reason = `low_confidence=${confidence_score} (< ${PASS_CONFIDENCE})`;
}

return {
  json: {
    ...session,
    meeting_type,
    confidence_score,
    summary,
    gate_decision: passes ? 'ingest' : 'archive',
    reject_reason,
  },
};

// Node: "Build Framework Request"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Stream 1 needs a *dense conceptual takeaway*, which is a summarisation task,
// so an LLM distils it (temperature 0, JSON mode). The Dual-Stream Parser then
// turns that JSON into the framework chunk text deterministically.
//
// It also returns `leader_questions`: first-person questions this session
// answers. They are used as extra index vectors (multi-vector / doc2query
// indexing) because bge-m3 question->passage similarity tops out ~0.55, below
// the brief's 0.70 / 0.65 gates, while question->question similarity for a
// genuine match is 0.72-0.77 and off-domain questions stay <= 0.57 (measured).
// -----------------------------------------------------------------------------
const s = $json;
const coaches = s.participants.filter((p) => p.is_team_member).map((p) => p.name);
const fullTranscript = s.transcript
  .map((t) => `[${t.timestamp ?? '--:--:--'}] ${t.speaker}: ${t.text.trim()}`)
  .join('\n');

const system = [
  'You distil executive-coaching sessions into reusable framework cards for a knowledge base.',
  `The coach is ${coaches.join(' / ') || 'the GenX team member'}.`,
  'Work only from what the coach actually says in the transcript, and keep the coach\'s own name for each framework.',
  'Write dense, specific sentences that someone could act on without reading the transcript.',
  'Return one JSON object in this shape:',
  '{"frameworks": [{',
  '  "name": "framework name as the coach calls it",',
  '  "problem": "the leadership problem it solves, 1-2 sentences",',
  '  "core_principle": "the central idea, 1-2 sentences",',
  '  "method": ["step 1", "step 2", "step 3"],',
  '  "key_question": "the diagnostic question or rule the coach gives, verbatim where possible",',
  '  "outcome": "what changes when the leader applies it"',
  '}],',
  ' "leader_questions": ["10 questions"]}',
  'Include one framework entry per distinct framework the coach teaches (usually one).',
  'For leader_questions, write 10 distinct questions this session\'s advice answers, the way a leader would type them to an executive coach:',
  'first person ("How should I...", "How do I...", "What do I do when..."), naming the concrete situation (the role, the symptom, the relationship),',
  'and covering different angles: the presenting problem, the underlying cause, the conversation to have, and the next step.',
].join('\n');

return {
  json: {
    ...s,
    framework_request: {
      model: $env.GROQ_MODEL || 'openai/gpt-oss-120b',
      temperature: 0,
      seed: 42,
      reasoning_effort: 'low',
      include_reasoning: false,
      max_tokens: 2500,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `Session ${s.session_id}: ${s.title}\n\nTranscript:\n${fullTranscript}` },
      ],
    },
  },
};

// Node: "Dual-Stream Parser"   (Code · Run Once for All Items)
// -----------------------------------------------------------------------------
// For every APPROVED coaching session, emit two streams of chunks:
//   Stream 1  framework     dense conceptual takeaway (from the LLM's framework card)
//   Stream 2  voice_sample  the coach's verbatim turns only, packed into
//                           400-700 character chunks on sentence boundaries
// Output: one n8n item per (chunk x index text), ready to be embedded.
//   Every chunk is indexed by its own passage text AND by each leader question
//   the session answers (multi-vector indexing). All rows of one chunk share a
//   chunk_key, and retrieval de-duplicates on it. `content` is always the real
//   framework card / verbatim coach text; only the vector's source text differs.
// -----------------------------------------------------------------------------
const MIN_CHARS = 400;
const MAX_CHARS = 700;

// ---------- Stream 2 helpers: verbatim coach dialogue ----------
const clean = (text) => text.replace(/\s+/g, ' ').trim();

// Split a turn into sentences, keeping punctuation and closing quotes attached.
function toSentences(text) {
  return clean(text)
    .split(/(?<=[.!?]["'’”)]?)\s+(?=["'‘“(]?[A-Z0-9])/)
    .map((s) => s.trim())
    .filter(Boolean);
}

// A sentence longer than MAX_CHARS (rare) is cut on a word boundary.
function capLength(sentence) {
  if (sentence.length <= MAX_CHARS) return [sentence];
  const parts = [];
  let rest = sentence;
  while (rest.length > MAX_CHARS) {
    const cut = rest.lastIndexOf(' ', MAX_CHARS);
    const at = cut > 0 ? cut : MAX_CHARS;
    parts.push(rest.slice(0, at).trim());
    rest = rest.slice(at).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

// Same turn -> joined with a space; a new turn -> blank line, so the rhythm
// of separate spoken turns is preserved inside a chunk.
function render(units) {
  return units
    .map((u, i) => (i === 0 ? '' : u.turn === units[i - 1].turn ? ' ' : '\n\n') + u.text)
    .join('');
}

function packVoiceChunks(coachTurns) {
  const units = [];
  coachTurns.forEach((turn, turnIndex) => {
    for (const sentence of toSentences(turn.text)) {
      for (const piece of capLength(sentence)) units.push({ text: piece, turn: turnIndex, ts: turn.timestamp });
    }
  });
  if (units.length === 0) return [];

  // 1) Greedy pack up to MAX_CHARS.
  const chunks = [];
  let current = [];
  for (const unit of units) {
    if (current.length && render([...current, unit]).length > MAX_CHARS) {
      chunks.push(current);
      current = [];
    }
    current.push(unit);
  }
  if (current.length) chunks.push(current);

  // 2) Rebalance a short tail: borrow whole sentences from the previous chunk
  //    while both stay inside the window; otherwise merge if the result fits.
  for (let i = chunks.length - 1; i > 0; i--) {
    const prev = chunks[i - 1];
    const last = chunks[i];
    while (render(last).length < MIN_CHARS && prev.length > 1) {
      const candidatePrev = prev.slice(0, -1);
      const candidateLast = [prev[prev.length - 1], ...last];
      if (render(candidatePrev).length < MIN_CHARS || render(candidateLast).length > MAX_CHARS) break;
      prev.pop();
      last.unshift(candidateLast[0]);
    }
    if (render(last).length < MIN_CHARS && render([...prev, ...last]).length <= MAX_CHARS) {
      chunks.splice(i - 1, 2, [...prev, ...last]);
    }
  }

  // 3) If sentence boundaries make a 400-700 split impossible (e.g. 836 chars of
  //    coach text => 458 + 384), give the short chunk a whole-sentence OVERLAP
  //    from the end of the previous chunk. Sentences stay intact and verbatim.
  const result = chunks.map((units) => ({ units, overlap: 0 }));
  for (let i = 1; i < result.length; i++) {
    const prev = chunks[i - 1];
    let k = prev.length - 1;
    while (render(result[i].units).length < MIN_CHARS && k >= 0) {
      const candidate = [prev[k], ...result[i].units];
      if (render(candidate).length > MAX_CHARS) break;
      result[i].units = candidate;
      result[i].overlap += 1;
      k -= 1;
    }
  }

  return result.map(({ units, overlap }) => ({
    content: render(units),
    timestamps: [...new Set(units.map((u) => u.ts))],
    overlap_sentences: overlap,
  }));
}

// ---------- Stream 1 helpers: framework card -> dense text ----------
const asList = (v) => (Array.isArray(v) ? v : v ? [v] : []).map((x) => clean(String(x))).filter(Boolean);

function parseFrameworks(reply) {
  try {
    if (reply.error) return { frameworks: [], questions: [], error: String(reply.error.message ?? reply.error) };
    const content = reply?.choices?.[0]?.message?.content ?? '';
    const cleaned = content.replace(/```(?:json)?/gi, '').trim();
    const parsed = JSON.parse(cleaned.slice(cleaned.indexOf('{'), cleaned.lastIndexOf('}') + 1));
    const list = Array.isArray(parsed.frameworks) ? parsed.frameworks : [parsed];
    const questions = [...new Set(asList(parsed.leader_questions))].slice(0, 12);
    return { frameworks: list.filter((f) => f && typeof f.name === 'string' && f.name.trim()), questions, error: null };
  } catch (err) {
    return { frameworks: [], questions: [], error: err.message };
  }
}

function frameworkText(fw, session, coachName) {
  const method = asList(fw.method);
  return [
    `Framework: ${clean(fw.name)} (taught by ${coachName}, session ${session.session_id})`,
    fw.problem && `Problem it solves: ${clean(fw.problem)}`,
    fw.core_principle && `Core principle: ${clean(fw.core_principle)}`,
    method.length && `How to run it: ${method.map((m, i) => `${i + 1}) ${m}`).join(' ')}`,
    fw.key_question && `Key question / rule: ${clean(fw.key_question)}`,
    fw.outcome && `Outcome: ${clean(fw.outcome)}`,
  ].filter(Boolean).join('\n');
}

// One row per index text: the passage itself + every leader question.
const indexTexts = (content, questions) => [
  { index_kind: 'passage', index_text: content },
  ...questions.map((q) => ({ index_kind: 'question', index_text: q })),
];

// ---------- Main ----------
const out = [];

$input.all().forEach((item, index) => {
  const { framework_request, ...session } = $('Build Framework Request').itemMatching(index).json;
  const coachNames = new Set(session.participants.filter((p) => p.is_team_member).map((p) => p.name));
  const coachName = [...coachNames].join(' / ') || 'coach';
  const baseMeta = {
    source: 'mock_transcripts.json',
    title: session.title,
    session_created_at: session.session_created_at,
    coach: coachName,
    meeting_type: session.meeting_type,
    confidence_score: session.confidence_score,
  };
  const sessionInfo = {
    session_id: session.session_id,
    title: session.title,
    meeting_type: session.meeting_type,
    confidence_score: session.confidence_score,
    summary: session.summary,
  };

  // Stream 1: framework
  const { frameworks, questions, error } = parseFrameworks(item.json);
  const frameworkChunks = frameworks.length
    ? frameworks.map((fw) => ({ content: frameworkText(fw, session, coachName), framework_name: clean(fw.name) }))
    : [{ // safe fallback: never lose an approved session because extraction failed
        content: `Coaching takeaway (session ${session.session_id}, ${coachName}): ${session.summary}`,
        framework_name: null,
        extraction_error: error,
      }];

  // Stream 2: voice_sample (coach turns only)
  const coachTurns = session.transcript.filter((t) => coachNames.has(t.speaker));
  const voiceChunks = packVoiceChunks(coachTurns);

  const frameworkName = frameworkChunks.find((fc) => fc.framework_name)?.framework_name ?? null;

  const emit = (stream_type, chunk_index, content, metadata) => {
    const chunk_key = `${session.session_id}:${stream_type}:${chunk_index}`;
    for (const idx of indexTexts(content, questions)) {
      out.push({
        json: {
          ...sessionInfo,
          stream_type,
          chunk_index,
          chunk_key,
          content,
          index_kind: idx.index_kind,
          index_text: idx.index_text,
          metadata: { ...metadata, chunk_key, index_kind: idx.index_kind, index_text: idx.index_text },
        },
        pairedItem: { item: index },
      });
    }
  };

  frameworkChunks.forEach((fc, i) => emit('framework', i, fc.content, {
    ...baseMeta,
    framework_name: fc.framework_name,
    char_count: fc.content.length,
    ...(fc.extraction_error ? { extraction_error: fc.extraction_error } : {}),
  }));

  voiceChunks.forEach((vc, i) => emit('voice_sample', i, vc.content, {
    ...baseMeta,
    framework_name: frameworkName,
    speaker: coachName,
    char_count: vc.content.length,
    within_400_700: vc.content.length >= MIN_CHARS && vc.content.length <= MAX_CHARS,
    turn_timestamps: vc.timestamps,
    overlap_sentences: vc.overlap_sentences,
  }));
});

return out;

// Node: "Build Vault Upsert SQL"   (Code · Run Once for All Items)
// -----------------------------------------------------------------------------
// Joins every chunk with its bge-m3 embedding and writes ONE transactional SQL
// statement per session: delete old rows -> insert fresh rows -> log decision.
// Re-running ingestion therefore always converges to the same table contents.
// -----------------------------------------------------------------------------
const EMBEDDING_DIM = 1024;

const toBase64 = (str) => (typeof Buffer !== 'undefined'
  ? Buffer.from(str, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(str))));
const text = (value) => `convert_from(decode('${toBase64(String(value ?? ''))}', 'base64'), 'UTF8')`;
const jsonb = (value) => `${text(JSON.stringify(value ?? {}))}::jsonb`;

function vectorLiteral(embedding, label) {
  if (!Array.isArray(embedding) || embedding.length !== EMBEDDING_DIM) {
    throw new Error(`${label}: expected a ${EMBEDDING_DIM}-dim embedding, got ${Array.isArray(embedding) ? embedding.length : typeof embedding}`);
  }
  if (!embedding.every((n) => Number.isFinite(n))) throw new Error(`${label}: embedding contains non-numeric values`);
  return `'[${embedding.join(',')}]'::vector(${EMBEDDING_DIM})`;
}

// Group chunks by session, preserving order.
const sessions = new Map();
$input.all().forEach((item, index) => {
  const chunk = $('Dual-Stream Parser').itemMatching(index).json;
  const label = `${chunk.chunk_key ?? `${chunk.session_id}/${chunk.stream_type}#${chunk.chunk_index}`} [${chunk.index_kind ?? 'passage'}]`;
  if (item.json.error) throw new Error(`${label}: embedding request failed: ${JSON.stringify(item.json.error)}`);
  const embedding = item.json.embeddings?.[0] ?? item.json.embedding;
  const row = { ...chunk, vector: vectorLiteral(embedding, label), inputIndex: index };
  if (!sessions.has(chunk.session_id)) sessions.set(chunk.session_id, []);
  sessions.get(chunk.session_id).push(row);
});

return [...sessions.entries()].map(([sessionId, rows]) => {
  const first = rows[0];
  const sid = text(sessionId);
  // Count distinct chunks (a chunk has several index vectors).
  const distinctChunks = (stream) => new Set(rows.filter((r) => r.stream_type === stream).map((r) => r.chunk_key)).size;
  const frameworkCount = distinctChunks('framework');
  const voiceCount = distinctChunks('voice_sample');

  const values = rows
    .map((r) => `  (${sid}, '${r.stream_type}', ${text(r.content)}, ${jsonb({ ...r.metadata, chunk_index: r.chunk_index })}, ${r.vector})`)
    .join(',\n');

  const sql = `
DELETE FROM knowledge_vault WHERE session_id = ${sid};

INSERT INTO knowledge_vault (session_id, stream_type, content, metadata, embedding) VALUES
${values};

DELETE FROM archived_sessions WHERE session_id = ${sid};

INSERT INTO ingestion_log
  (session_id, title, meeting_type, confidence_score, summary, decision, reason, framework_chunks, voice_chunks, processed_at)
VALUES
  (${sid}, ${text(first.title)}, ${text(first.meeting_type)}, ${Number(first.confidence_score) || 0}, ${text(first.summary)},
   'ingested', NULL, ${frameworkCount}, ${voiceCount}, now())
ON CONFLICT (session_id) DO UPDATE SET
  title = EXCLUDED.title, meeting_type = EXCLUDED.meeting_type, confidence_score = EXCLUDED.confidence_score,
  summary = EXCLUDED.summary, decision = EXCLUDED.decision, reason = NULL,
  framework_chunks = EXCLUDED.framework_chunks, voice_chunks = EXCLUDED.voice_chunks, processed_at = now();

SELECT ${sid} AS session_id, 'ingested' AS decision, ${frameworkCount} AS framework_chunks, ${voiceCount} AS voice_chunks, ${rows.length} AS index_vectors;
`;

  return {
    json: { session_id: sessionId, framework_chunks: frameworkCount, voice_chunks: voiceCount, index_vectors: rows.length, sql },
    pairedItem: rows.map((r) => ({ item: r.inputIndex })),
  };
});

// Node: "Build Archive SQL"   (Code · Run Once for Each Item)
// -----------------------------------------------------------------------------
// Rejected sessions go to a flat relational table. No embeddings are created.
// Text is passed to Postgres as base64 and decoded server-side, so quotes,
// backslashes and "$" in transcripts can never break or inject into the SQL.
// Re-running the workflow is idempotent (upserts + cleanup of stale vault rows).
// -----------------------------------------------------------------------------
const toBase64 = (str) => (typeof Buffer !== 'undefined'
  ? Buffer.from(str, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(str))));
const text = (value) => `convert_from(decode('${toBase64(String(value ?? ''))}', 'base64'), 'UTF8')`;
const jsonb = (value) => `${text(JSON.stringify(value ?? null))}::jsonb`;
const tsOrNull = (value) => (value ? `${text(value)}::timestamptz` : 'NULL');
const num = (value) => (Number.isFinite(Number(value)) ? Number(value) : 0);

const s = $json;
const sid = text(s.session_id);

const sql = `
INSERT INTO archived_sessions
  (session_id, title, session_created_at, meeting_type, confidence_score, summary, reject_reason, participants, transcript, archived_at)
VALUES
  (${sid}, ${text(s.title)}, ${tsOrNull(s.session_created_at)}, ${text(s.meeting_type)}, ${num(s.confidence_score)},
   ${text(s.summary)}, ${text(s.reject_reason)}, ${jsonb(s.participants)}, ${jsonb(s.transcript)}, now())
ON CONFLICT (session_id) DO UPDATE SET
  title = EXCLUDED.title, session_created_at = EXCLUDED.session_created_at,
  meeting_type = EXCLUDED.meeting_type, confidence_score = EXCLUDED.confidence_score,
  summary = EXCLUDED.summary, reject_reason = EXCLUDED.reject_reason,
  participants = EXCLUDED.participants, transcript = EXCLUDED.transcript, archived_at = now();

DELETE FROM knowledge_vault WHERE session_id = ${sid};

INSERT INTO ingestion_log
  (session_id, title, meeting_type, confidence_score, summary, decision, reason, framework_chunks, voice_chunks, processed_at)
VALUES
  (${sid}, ${text(s.title)}, ${text(s.meeting_type)}, ${num(s.confidence_score)}, ${text(s.summary)}, 'archived', ${text(s.reject_reason)}, 0, 0, now())
